
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state;try{state=JSON.parse(localStorage.unichat||'null')}catch{}state=state||{name:'Chimdike Amah',school:'University of Port Harcourt',bio:'Law student. Building ideas that bring students together.',posts:[],likes:[],saved:[],following:[],joined:[],rsvps:[],messages:[],comments:{},dark:false};let page='Home',feed='Across Schools',query='',attachment=null;const schools=['University of Port Harcourt','University of Lagos','University of Nigeria, Nsukka','Rivers State University','Other institution'];const people=[['AO','Amara Okafor','UNILAG · Computer Science'],['DT','David Thompson','UNN · Engineering'],['ZE','Zainab Eze','RSU · Business Administration']];const groups=[['⚖','Law Students Network','Case discussions, moot preparation and a community that gets it.','1.2k'],['⌘','Campus Builders','Turn your next big idea into something real.','846'],['✎','The Study Circle','Find your focus. Find your study people.','623'],['♫','Creatives Collective','Music, art, photography and everything in between.','512']];const seed=[{id:'a',name:'Amara Okafor',initial:'AO',school:'University of Lagos',dept:'Computer Science · 300 Level',time:'24 min ago',text:'Your next collaborator might be on another campus. ✨\nWe’re putting together a student design & tech circle. If you love building things, learning together, or just asking “what if?” — let’s connect!',likes:42,comments:8,tag:'#BuildInPublic  #StudentCreators',poster:true},{id:'b',name:'Timi Williams',initial:'TW',school:'University of Port Harcourt',dept:'Law · 300 Level',time:'1 hr ago',text:'A little reminder for the new week: you don’t have to figure everything out alone. Who’s up for a library study session this week? 📚',likes:27,comments:5,tag:'#StudyTogether  #UniPort'},{id:'c',name:'Zainab Eze',initial:'ZE',school:'Rivers State University',dept:'Business Administration',time:'2 hrs ago',text:'What’s one thing you wish you knew before your first year? Drop your best campus survival tip below 👇',likes:63,comments:17,tag:'#CampusLife'}];function save(){localStorage.unichat=JSON.stringify(state)}function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3000)}function theme(){state.dark=!state.dark;save();document.body.classList.toggle('dark',state.dark)}document.body.classList.toggle('dark',state.dark);const items=[['⌂','Home'],['⌕','Discover'],['♧','Communities'],['▣','Events'],['✉','Messages'],['♡','Bookmarks'],['♙','Profile']];function go(p){page=p;query='';render();window.scrollTo(0,0)}function nav(){ $('#nav').innerHTML=items.map(([i,n])=>`<button class="${page===n?'active':''}" onclick="go('${n}')"><i>${i}</i>${n}${n==='Messages'?'<span class="pill">2</span>':''}</button>`).join('');$('#mobile').innerHTML=items.filter(x=>['Home','Discover','Messages','Profile'].includes(x[1])).map(([i,n])=>`<button onclick="go('${n}')" class="${page===n?'active':''}"><i>${i}</i>${n}</button>`).join('');$('#headername').textContent=state.name;$('#people').innerHTML=people.map((p,i)=>person(p,i)).join('')}function person(p,i){return `<div class="row person"><span class="avatar" style="background:${['#e8e0f8','#e4f2eb','#fff0db'][i]}">${p[0]}</span><div><b class="small">${p[1]}</b><div class="muted" style="font-size:10px;margin-top:4px">${p[2]}</div></div><button class="follow" onclick="follow(${i})">${state.following.includes(i)?'Following':'＋ Follow'}</button></div>`}function follow(i){state.following=state.following.includes(i)?state.following.filter(x=>x!==i):[...state.following,i];save();render()}function all(){return [...state.posts,...seed]}function post(p){const comments=state.comments[p.id]||[];return `<article class="card post" id="post-${p.id}"><div class="row"><span class="avatar">${esc(p.initial)}</span><div class="meta"><strong>${esc(p.name)}</strong><div class="small muted">${esc(p.school)} · ${esc(p.time)}</div></div><button style="margin-left:auto" aria-label="Report post" onclick="report('${p.id}')">•••</button></div><p style="white-space:pre-line">${xRich(p.text)}</p>${p.tag?`<div style="color:var(--blue);font-size:12px">${esc(p.tag)}</div>`:''}${p.poster?'<div class="poster"><span>THE CAMPUS CREATORS COLLECTIVE</span><h2>Big ideas.<br>No campus limits.</h2><p style="font-size:12px;margin-bottom:0">Create. Collaborate. Make your mark. ↗</p></div>':''}${p.media?`<${p.video?'video controls':'img'} src="${p.media}" style="width:100%;max-height:350px;object-fit:cover;border-radius:10px;margin:15px 0" ${p.video?'':'alt="Post attachment"'}>`:''}<div class="actions" style="margin-top:18px"><button class="${state.likes.includes(p.id)?'on':''}" onclick="toggle('likes','${p.id}')">${state.likes.includes(p.id)?'♥':'♡'} ${p.likes+Number(state.likes.includes(p.id))}</button><button onclick="comment('${p.id}')">♧ ${p.comments+comments.length}</button><button onclick="share('${p.id}')">↗ Share</button><button class="${state.saved.includes(p.id)?'on':''}" style="margin-left:auto" onclick="toggle('saved','${p.id}')">${state.saved.includes(p.id)?'▣ Saved':'▢ Save'}</button></div>${comments.map(c=>xComment(c)).join('')}</article>`}function toggle(k,id){state[k]=state[k].includes(id)?state[k].filter(x=>x!==id):[...state[k],id];save();render()}function composer(){return `<div class="card composer"><div class="row"><span class="avatar">CA</span><textarea id="posttext" placeholder="What's happening in your world?" aria-label="Write a post"></textarea></div><div id="attachment" class="small muted"></div><div class="row between divider"><div class="row"><button onclick="attach()" style="color:#39826c">▧ <span class="small">Photo / Video</span></button><button onclick="go('Events')" style="color:#b58b42">▣ <span class="small">Event</span></button></div><button class="primary" onclick="publish()">Post ↗</button></div></div>`}function render(){nav();let html='';if(page==='Home'){html=`<div class="card welcome"><span class="eyebrow">YOUR CAMPUS. A BIGGER WORLD.</span><h1>Good things start with a hello 👋</h1><p>Meet your people. Share your world.<br>Make your university years count.</p><span class="pill">✦ A space for every student</span></div>${composer()}<div class="row between"><h3>Your feed</h3><span class="small muted">✦ Fresh perspectives</span></div><div class="tabs">${['Across Schools','My Campus','Following'].map(t=>`<button class="${feed===t?'active':''}" onclick="feed='${t}';render()">${t}</button>`).join('')}</div>`;let posts=all().filter(p=>feed==='My Campus'?p.school===state.school:feed==='Following'?p.name===state.name||people.some((q,i)=>q[1]===p.name&&state.following.includes(i)):true);html+=posts.map(post).join('')||'<div class="card empty">Follow students to see their posts here.</div>'}else if(page==='Communities'){html=title('Find your circle','A shared interest is all it takes.')+'<div class="grid">'+groups.map((g,i)=>`<div class="card community"><span style="font-size:30px;color:var(--blue)">${g[0]}</span><h3>${g[1]}</h3><p class="muted small">${g[2]}</p><p class="small muted">${g[3]} members · Across schools</p><button class="primary" onclick="join(${i})">${state.joined.includes(i)?'✓ Joined':'Join community'}</button></div>`).join('')+'</div>'}else if(page==='Discover'){html=title('A bigger world awaits','Discover people and conversations beyond your campus.')+`<input class="input" placeholder="Search students, communities or posts" value="${esc(query)}" oninput="query=this.value;results()" aria-label="Search"><div id="results"></div>`}else if(page==='Events'){html=title('Make time for something good','On campus and beyond. Find your next experience.')+[['21','NOV','Campus Creators Meetup','University of Port Harcourt · 2:00 PM','Meet students building the next big thing.'],['28','NOV','Intercampus Study Sprint','Online · 5:00 PM','Two hours of focused work, together.'],['05','DEC','Student Founders Roundtable','University of Lagos · 11:00 AM','Ideas, honest conversations and new connections.']].map((e,i)=>`<div class="card"><div class="row"><div class="eventdate">${e[0]}<small>${e[1]} 2026</small></div><div><h3 style="margin:0 0 8px">${e[2]}</h3><div class="muted small">${e[3]}</div></div></div><p>${e[4]}</p><button class="follow" onclick="rsvp(${i},this)">${state.rsvps.includes(i)?'✓ Interested':'♡ Interested'}</button></div>`).join('')}else if(page==='Bookmarks'){html=title('Your saved finds','Keep good conversations close.')+(all().filter(p=>state.saved.includes(p.id)).map(post).join('')||'<div class="card empty">Save a post and it will appear here.</div>')}else if(page==='Profile'){html=`<div class="card"><div class="poster" style="min-height:130px"><span>CONNECT. GROW. SUCCEED.</span><h2 style="font-size:25px">Your story starts here.</h2></div><span class="avatar" style="width:70px;height:70px;font-size:23px">CA</span><button class="follow" style="float:right" onclick="editProfile()">Edit profile</button><h1>${esc(state.name)}</h1><p class="muted">${esc(state.school)}</p><p>${esc(state.bio)}</p><div class="row divider"><b>${state.posts.length} <span class="muted small">Posts</span></b><b>${state.following.length} <span class="muted small">Following</span></b><b>${state.joined.length} <span class="muted small">Communities</span></b></div></div><h3>Your posts</h3>${state.posts.map(post).join('')||'<div class="card empty">Share your first hello with the community.</div>'}`}else if(page==='Messages'){html=title('Your conversations','A new connection is a message away.')+`<div class="card"><div class="row"><span class="avatar">AO</span><div><b>Amara Okafor</b><p class="small muted">Sample conversation · messages stay on this device</p></div></div><div class="divider"><div class="chatbubble">Hey! Welcome to UniChat 👋 What are you working on this semester?</div>${state.messages.map(m=>`<div class="chatbubble mine">${esc(m)}</div>`).join('')}</div><form class="row divider" onsubmit="event.preventDefault();send()"><input id="msg" class="input" placeholder="Write a message…" aria-label="Message" style="margin:0"><button class="primary">Send</button></form></div>`}else if(page==='Notifications'){html=title('You’re in the loop','Updates from your UniChat world.')+['Welcome to UniChat. Complete your profile and say hello.','Campus Creators Meetup is coming up on 21 November.','Explore communities to find students who share your interests.'].map(t=>`<div class="card row"><span class="avatar">✦</span><div>${t}<p class="muted small">Sample notification</p></div></div>`).join('')}$('#main').innerHTML=html;if(page==='Discover')results()}function title(h,p){return `<h1 class="sectiontitle">${h}</h1><p class="muted" style="margin-bottom:25px">${p}</p>`}function results(){const q=query.toLowerCase();$('#results').innerHTML='<div class="card"><h3>People</h3>'+people.map((p,i)=>p.join(' ').toLowerCase().includes(q)?person(p,i):'').join('')+'</div>'+all().filter(p=>(p.text+p.name+p.school).toLowerCase().includes(q)).map(post).join('')}function join(i){state.joined=state.joined.includes(i)?state.joined.filter(x=>x!==i):[...state.joined,i];save();render()}function rsvp(i,b){state.rsvps=state.rsvps.includes(i)?state.rsvps.filter(x=>x!==i):[...state.rsvps,i];save();b.textContent=state.rsvps.includes(i)?'✓ Interested':'♡ Interested'}function compose(){go('Home');$('#posttext').focus()}function attach(){$('#media').click()}$('#media').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2500000)return toast('Choose a file smaller than 2.5 MB for this preview.');const data=await new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsDataURL(f)});attachment={data,video:f.type.startsWith('video')};$('#attachment').textContent=f.name+' attached'};function publish(){const text=$('#posttext').value.trim();if(!text&&!attachment)return toast('Write something or add a photo first.');const p={id:'p'+Date.now(),name:state.name,initial:'CA',school:state.school,time:'Just now',text,likes:0,comments:0,media:attachment?.data,video:attachment?.video};state.posts.unshift(p);try{save()}catch{state.posts.shift();return toast('Device storage is full. Try a smaller attachment.')}attachment=null;feed='Across Schools';render();toast('Your post is published on this device')}function modal(h){$('#modal').innerHTML='<button class="close" onclick="document.querySelector(\'#modal\').close()" aria-label="Close">×</button>'+h;$('#modal').showModal()}function comment(id){modal(`<h2>Join the conversation</h2><textarea id="reply" class="input" placeholder="Write a thoughtful reply…"></textarea><button class="primary" onclick="addComment('${id}')">Post reply</button>`)}function addComment(id){const t=$('#reply').value.trim();if(!t)return;state.comments[id]=[...(state.comments[id]||[]),t];save();$('#modal').close();render()}function report(id){modal(`<h2>Report a post</h2><p class="muted">Choose a reason. This preview records reports locally; no moderation team is connected yet.</p><select id="reason" class="input"><option>Harassment or bullying</option><option>Spam or scam</option><option>Harmful content</option><option>Other</option></select><button class="primary" onclick="localStorage.setItem('unichat-report-${id}',document.querySelector('#reason').value);document.querySelector('#modal').close();toast('Report recorded on this device')">Record report</button>`)}function editProfile(){modal(`<h2>Make it yours</h2><label>Full name<input id="name" class="input" maxlength="60" value="${esc(state.name)}"></label><label>Institution<select id="school" class="input">${schools.map(s=>`<option ${s===state.school?'selected':''}>${s}</option>`).join('')}</select></label><label>Bio<textarea id="bio" class="input" maxlength="220">${esc(state.bio)}</textarea></label><button class="primary" onclick="updateProfile()">Save profile</button>`)}function updateProfile(){if(!$('#name').value.trim())return toast('Please enter your name.');state.name=$('#name').value.trim();state.school=$('#school').value;state.bio=$('#bio').value;save();$('#modal').close();render();toast('Profile updated')}function send(){const t=$('#msg').value.trim();if(!t)return;state.messages.push(t);save();render()}async function share(id){try{await navigator.clipboard.writeText(location.origin+'/#post-'+id);toast('Post link copied')}catch{toast('Use your browser’s share option to share this preview.')}}$('#search').oninput=e=>{query=e.target.value;page='Discover';const q=query;render();query=q;const inp=$('#main input');inp.value=q;results()};

let session=null,cloudPosts=[],cfg={name:'UniChat',slogan:'Connect. Grow. Succeed.',heading:'Good things start with a hello 👋',description:'Meet your people. Share your world. Make your university years count.',color:'#2161e8',logo:'',favicon:'',support:'',schools:schools.join('\n'),texts:{},features:{registration:true,posting:true,uploads:true,communities:true,events:true,messaging:true},guidelines:'Be respectful. Protect personal information. No harassment, scams or spam.',privacy:'Your profile and posts are visible to other registered students. Contact support for account assistance.'},draft=null,adminTab='Branding';
const baseRender=render,baseNav=nav,baseAll=all;

function useConfig(c){document.documentElement.style.setProperty('--blue',c.color||'#2161e8');document.title=c.name+' — '+c.slogan;const brand=$('.brand');brand.innerHTML=(c.logo?'<img src="'+esc(c.logo)+'" alt="Site logo" style="width:38px;height:38px;object-fit:contain">':'<span class="logo">u</span>')+esc(c.name)+'<span style="color:var(--blue)">.</span>';let icon=document.querySelector('link[rel="icon"]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.append(icon)}icon.href=c.favicon||c.logo||'/favicon.svg';const welcome=$('.welcome');if(welcome){welcome.querySelector('h1').textContent=c.heading;welcome.querySelector('p').textContent=c.description}document.querySelectorAll('.sidebarfoot').forEach(el=>{el.innerHTML='<button onclick="policy(\'guidelines\')">Community guidelines</button><br><button onclick="policy(\'privacy\')">Privacy</button> · <button onclick="policy(\'support\')">Support</button><br>© 2026 '+esc(c.name)+'<br><button onclick="theme()">◐ Switch appearance</button>'});const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(n.parentElement?.closest('script,style,dialog,#adminpanel,.post,.chatbubble,input,textarea'))continue;const key=n.textContent.trim();if(c.texts?.[key])n.textContent=c.texts[key]}for(const [name,key] of [['Communities','communities'],['Events','events'],['Messages','messaging']])if(c.features?.[key]===false)document.querySelectorAll('nav button').forEach(b=>{if(b.textContent.includes(name))b.hidden=true});}
nav=function(){baseNav();if(session?.admin)$('#nav').insertAdjacentHTML('beforeend','<button onclick="go(\'Admin\')">⚙ Owner dashboard</button>');const h=$('.headerend');if(!$('#accountaction'))h.insertAdjacentHTML('beforeend','<a id="accountaction" href="/signout-with-chatgpt?return_to=%2F" style="font-size:11px;color:var(--muted)">Sign out</a>');const span=$('.headerend .username .muted');if(span)span.textContent=state.school;};
all=()=>[...cloudPosts,...seed];
save=function(){localStorage.setItem('unichat-appearance',String(state.dark));if(session?.profile)api('state',{...state,posts:[]}).catch(e=>toast(e.message))};
render=function(){if(page==='Admin'){nav();adminPage();return}if(!session?.profile)return;const key={Communities:'communities',Events:'events',Messages:'messaging'}[page];if(key&&cfg.features?.[key]===false){page='Home';toast('This feature is currently paused.')}baseRender();useConfig(cfg);document.querySelectorAll('.demo').forEach(e=>e.textContent='Early access · Student accounts and posts now sync across devices. Messaging is still a sample conversation.');if(page==='Profile')$('#main').innerHTML=$('#main').innerHTML.replace('Your posts','Your posts');};
publish=async function(){const text=$('#posttext').value.trim();try{const r=await api('post',{text,media:attachment?.data,video:attachment?.video});cloudPosts.unshift(r.post);state.posts=cloudPosts.filter(p=>p.author_id===authUser.id);attachment=null;feed='Across Schools';render();toast('Post published')}catch(e){toast(e.message)}};
function registration(edit=false){const initial=session.profile||(!edit?authUser?.user_metadata:null)||{};modal('<h2>'+(edit?'Edit your profile':'Welcome to '+esc(cfg.name))+'</h2><p class="muted">'+(edit?'Keep your student details up to date.':'Complete your student registration. Your email is secured by Supabase authentication.')+'</p><form onsubmit="event.preventDefault();register()">'+[['name','Full name'],['username','Username'],['department','Department']].map(([k,l])=>'<label>'+l+'<input class="input" id="reg-'+k+'" required maxlength="80" value="'+esc(initial[k]||'')+'"></label>').join('')+'<label>Email<input class="input" value="'+esc(session.user.email)+'" disabled></label><label>School<select class="input" id="reg-school">'+[...new Set([initial.school,...cfg.schools.split('\n')].filter(Boolean))].map(s=>'<option '+(s===initial.school?'selected':'')+'>'+esc(s)+'</option>').join('')+'</select></label><label>Level<select id="reg-level" class="input">'+['Diploma','100 Level','200 Level','300 Level','400 Level','500 Level','600 Level','Postgraduate','Other'].map(s=>'<option '+(s===initial.level?'selected':'')+'>'+s+'</option>').join('')+'</select></label><label>Bio<textarea class="input" id="reg-bio" maxlength="300">'+esc(initial.bio||'')+'</textarea></label><p class="small muted">Profile details are visible to other students. Read the <button type="button" onclick="toast(cfg.guidelines)">community guidelines</button> before posting.</p><button class="primary" type="submit">'+(edit?'Save profile':'Complete registration')+'</button><p class="small" id="reg-error" role="alert"></p></form>');if(!edit){$('#modal .close').hidden=true;$('#modal').oncancel=e=>e.preventDefault()}}
async function register(){const data={};for(const k of ['name','username','school','department','level','bio'])data[k]=$('#reg-'+k).value;try{await api('profile',data);session.profile=data;Object.assign(state,data);$('#modal').close();$('#modal').oncancel=null;render();toast('Profile saved')}catch(e){$('#reg-error').textContent=e.message}}
editProfile=()=>registration(true);updateProfile=register;
function policy(key){modal('<h2>'+({guidelines:'Community guidelines',privacy:'Privacy',support:'Contact support'}[key])+'</h2><p style="white-space:pre-wrap;line-height:1.8">'+esc(cfg[key]||'Support contact has not been set yet.')+'</p>')}
function configForm(){const fields=adminTab==='Branding'?[['name','Site name'],['slogan','Slogan'],['color','Primary colour'],['heading','Welcome heading'],['description','Welcome description']]:adminTab==='Policies'?[['guidelines','Community guidelines'],['privacy','Privacy information'],['support','Support contact']]:[['schools','Schools — one per line']];return fields.map(([k,l])=>'<label style="display:block;margin:15px 0">'+l+(k==='color'?'<input type="color" id="cfg-'+k+'" class="input" value="'+esc(draft[k])+'">':'<textarea id="cfg-'+k+'" class="input" rows="'+(k==='schools'?8:2)+'">'+esc(draft[k]||'')+'</textarea>')+'</label>').join('')}
async function adminPage(){if(!session.admin)return;draft=draft||structuredClone(cfg);$('#main').innerHTML='<h1 class="sectiontitle">Owner dashboard</h1><p class="muted">Edit, preview and publish. Changes apply to every student.</p><div class="tabs" style="overflow:auto">'+['Branding','Texts','Schools','Features','Policies','Students','Posts','History'].map(t=>'<button class="'+(adminTab===t?'active':'')+'" onclick="collectDraft();adminTab=\''+t+'\';adminPage()">'+t+'</button>').join('')+'</div><div class="card" id="adminpanel"></div><div class="row" style="flex-wrap:wrap"><button class="follow" onclick="saveDraft()">Save draft</button><button class="follow" onclick="previewDraft()">Preview draft</button><button class="primary" onclick="publishDraft()">Publish changes</button></div><p class="small muted">Publishing saves a version you can restore later. Software features still require development.</p>';
const panel=$('#adminpanel');if(['Branding','Schools','Policies'].includes(adminTab)){panel.innerHTML=configForm();if(adminTab==='Branding')panel.insertAdjacentHTML('beforeend',['logo','favicon'].map(k=>'<label style="display:block;margin:15px 0">'+k+'<input type="file" accept="image/png,image/jpeg,image/webp" onchange="uploadBrand(this,\''+k+'\')"><button class="follow" onclick="draft.'+k+'=\'\';toast(\'Image cleared in draft\')">Clear</button></label>').join(''));}else if(adminTab==='Features')panel.innerHTML=Object.keys(draft.features).map(k=>'<label class="row" style="padding:14px"><input type="checkbox" id="flag-'+k+'" '+(draft.features[k]?'checked':'')+'> '+k[0].toUpperCase()+k.slice(1)+'</label>').join('')+'<p class="small muted">Publish changes to apply these feature settings for students.</p>';else if(adminTab==='Texts')panel.innerHTML='<p class="muted">Replace interface text by entering its exact current wording. Student posts and private messages are excluded.</p><label>Original text<input class="input" id="textfrom"></label><label>Replacement<input class="input" id="textto"></label><button class="follow" onclick="addText()">Add replacement</button><div>'+Object.entries(draft.texts).map(([k,v])=>'<p>'+esc(k)+' → '+esc(v)+'</p>').join('')+'</div>';else{panel.textContent='Loading…';try{const r=await api('adminList');if(adminTab==='Students')panel.innerHTML=r.users.map(u=>'<div class="divider"><b>'+esc(u.name)+'</b> @'+esc(u.username)+'<p class="muted small">'+esc(u.school)+' · '+esc(u.department)+' · '+esc(u.level)+'</p><button class="follow" onclick="suspendUser(\''+u.id+'\','+(u.status!=='suspended')+')">'+(u.status==='suspended'?'Restore account':'Suspend account')+'</button></div>').join('')||'No registered students yet.';if(adminTab==='History')panel.innerHTML=r.versions.map(v=>'<div class="row between divider"><span>'+esc(new Date(v.created).toLocaleString())+'</span><button class="follow" onclick="restoreVersion(\''+v.id+'\')">Restore as draft</button></div>').join('')||'Publish your first change to start version history.';if(adminTab==='Posts')panel.innerHTML=cloudPosts.map(p=>'<div class="divider"><b>'+esc(p.name)+'</b><p>'+esc(p.text)+'</p><button class="follow" onclick="removePost(\''+p.id+'\')">Remove post</button></div>').join('')||'No student posts yet.';}catch(e){panel.textContent=e.message}}}
function collectDraft(){if(!draft)return;document.querySelectorAll('[id^="cfg-"]').forEach(e=>draft[e.id.slice(4)]=e.value);document.querySelectorAll('[id^="flag-"]').forEach(e=>draft.features[e.id.slice(5)]=e.checked)}function addText(){const k=$('#textfrom').value.trim(),v=$('#textto').value.trim();if(k&&v){draft.texts[k]=v;adminPage()}}async function uploadBrand(input,k){const f=input.files[0];if(!f)return;if(f.size>700000)return toast('Please choose an image under 700 KB.');draft[k]=await new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsDataURL(f)});toast('Image added to draft')}async function saveDraft(){collectDraft();try{await api('draft',draft);toast('Draft saved')}catch(e){toast(e.message)}}function previewDraft(){collectDraft();if(draft.communities)groups.splice(0,groups.length,...draft.communities);page='Home';baseRender();useConfig(draft);$('#main').insertAdjacentHTML('afterbegin','<div class="card row between" style="border:2px solid var(--blue)"><b>Draft preview · only you see these changes</b><button class="follow" onclick="go(\'Admin\')">Back to dashboard</button></div>')}async function publishDraft(){collectDraft();try{await api('publish',draft);cfg=structuredClone(draft);toast('Changes published for all students');adminPage()}catch(e){toast(e.message)}}async function restoreVersion(id){try{const r=await api('restore',null,{id});draft=r.data;adminTab='Branding';adminPage();toast('Version restored as draft. Preview before publishing.')}catch(e){toast(e.message)}}async function suspendUser(id,suspended){try{await api('suspend',null,{id,suspended});adminPage()}catch(e){toast(e.message)}}async function removePost(id){try{await api('removePost',null,{id});cloudPosts=cloudPosts.filter(p=>p.id!==id);adminPage()}catch(e){toast(e.message)}}

