async function uploadData(data,bucket){const blob=await(await fetch(data)).blob();const ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp','image/gif':'gif','video/mp4':'mp4'}[blob.type];if(!ext)throw Error('Use a PNG, JPEG, WebP, GIF or MP4 file.');const path=authUser.id+'/'+crypto.randomUUID()+'.'+ext;checked(await client.storage.from(bucket).upload(path,blob,{contentType:blob.type,upsert:false}));return path}
