 if(!action){const auth=checked(await client.auth.getUser());authUser=auth.user;if(!authUser)throw Error('Sign in to continue.');const owner=checked(await client.rpc('unichat_is_owner'));const profiles=await tableRows('profiles',q=>q.eq('id',authUser.id));const p=profiles[0];if(p?.status==='suspended'&&!owner)throw Error('Your account is suspended. Contact support.');const config=(await tableRows('settings',q=>q.eq('id','published')))[0];let rows=[];if(p){const [personal,posts]=await Promise.all([tableRows('content',q=>q.eq('id','state:'+authUser.id)),tableRows('content',q=>q.eq('kind','post').order('created_at',{ascending:false}).limit(100))]);const ids=posts.map(x=>x.id);const interactions=ids.length?await tableRows('content',q=>q.in('kind',['like','comment']).in('data->>postId',ids).limit(5000)):[];rows=[...personal,...posts,...interactions];}const posts=await signedMedia(rows.filter(x=>x.kind==='post').map(x=>({...x.data,id:x.id,author_id:x.owner,created_at:x.created_at})));return {user:{id:authUser.id,email:authUser.email},profile:p?.data||null,admin:owner,settings:config?.data||null,state:rows.find(x=>x.kind==='state'&&x.owner===authUser.id)?.data||null,posts,interactions:rows.filter(x=>['like','comment'].includes(x.kind)).map(x=>({...x.data,id:x.id,owner:x.owner,kind:x.kind}))};}
