async function loadStudents(){students=await tableRows('profiles',q=>q.eq('status','active').neq('id',authUser.id).limit(100));}
const samplePerson=person;person=function(p,i){return samplePerson(p,i)};
const beforeSupabaseRender=render;render=function(){if(!session?.profile)return;if(page==='Messages'){nav();$('#main').innerHTML='<div class="card">Loading conversations…</div>';messagesPage();return}beforeSupabaseRender();if(page==='Messages'){messagesPage();return}if(page==='Discover')studentDiscovery();if(page==='Home'&&state.following.some(x=>typeof x==='string')&&feed==='Following'){$('#main').querySelectorAll('.post').forEach(e=>e.remove());const posts=cloudPosts.filter(p=>p.author_id===authUser.id||state.following.includes(p.author_id));$('#main').insertAdjacentHTML('beforeend',posts.map(post).join(''));}if(page==='Profile'){const posts=cloudPosts.filter(p=>p.author_id===authUser.id);state.posts=posts;}if(page==='Home'&&$('#people'))$('#people').innerHTML=students.slice(0,3).map(studentCard).join('')||'<p class="small muted">New students will appear here as they join.</p>';};
function studentCard(u){return '<div class="row person"><span class="avatar">'+esc((u.data.name||'S').split(' ').map(s=>s[0]).slice(0,2).join(''))+'</span><div><b>'+esc(u.data.name)+'</b><p class="small muted">@'+esc(u.username)+' · '+esc(u.data.school)+'</p><button class="follow" onclick="followStudent(\''+u.id+'\')">'+(state.following.includes(u.id)?'Following':'＋ Follow')+'</button> <button class="follow" onclick="openChat(\''+u.id+'\')">Message</button></div></div>'}
function followStudent(id){state.following=state.following.includes(id)?state.following.filter(x=>x!==id):[...state.following,id];save();render()}
function studentDiscovery(){const box=$('#results');if(!box)return;const q=query.toLowerCase();box.innerHTML='<div class="card"><h3>Students</h3>'+students.filter(u=>(u.data.name+' '+u.username+' '+u.data.school).toLowerCase().includes(q)).map(studentCard).join('')+'</div>'+cloudPosts.filter(p=>(p.name+p.text+p.school).toLowerCase().includes(q)).map(post).join('')}
results=studentDiscovery;
async function openChat(id){selectedChat=id;go('Messages')}
async function messagesPage(){if(!cfg.features.messaging){$('#main').innerHTML='<div class="card">Messaging is currently paused.</div>';return}try{if(!students.length)await loadStudents();const rows=await tableRows('content',q=>q.eq('kind','message').order('created_at',{ascending:true}).limit(500));const partner=students.find(u=>u.id===selectedChat);$('#main').innerHTML=title('Your conversations','Private conversations across campuses.')+'<div class="card"><div class="row" style="flex-wrap:wrap">'+students.map(u=>'<button class="follow" onclick="openChat(\''+u.id+'\')">'+esc(u.data.name)+'</button>').join('')+'</div>'+(partner?'<h3 class="divider">'+esc(partner.data.name)+'</h3><div id="chatlog" aria-live="polite">'+rows.filter(r=>(r.owner===authUser.id&&r.data.recipient===selectedChat)||(r.owner===selectedChat&&r.data.recipient===authUser.id)).map(m=>'<div class="chatbubble '+(m.owner===authUser.id?'mine':'')+'">'+esc(m.data.text)+'<div style="font-size:10px;opacity:.65;margin-top:6px">'+esc(new Date(m.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))+'</div></div>').join('')+'</div><form class="row divider" onsubmit="event.preventDefault();send()"><input id="msg" class="input" placeholder="Write a message…" aria-label="Message" maxlength="4000" required style="margin:0"><button class="primary">Send</button></form>':'<div class="empty">'+(students.length?'Choose a student to start a conversation.':'Invite another student to join, then start your first conversation.')+'</div>')+'</div>';}catch(e){toast(e.message)}}
send=async function(){const text=$('#msg')?.value.trim();if(!text||!selectedChat)return;try{checked(await client.from('unichat_content').insert({id:crypto.randomUUID(),owner:authUser.id,kind:'message',data:{recipient:selectedChat,text}}));await messagesPage()}catch(e){toast(e.message)}};
// Label starter content explicitly until a real community replaces it.
const realAll=all;all=()=>cloudPosts.length?cloudPosts:seed.map(p=>({...p,name:p.name+' · Sample'}));
client.auth.onAuthStateChange((event)=>{if(event==='PASSWORD_RECOVERY'){recoveryMode=true;setTimeout(passwordReset,0);}if(event==='SIGNED_OUT')setTimeout(()=>authScreen(),0)});
window.addEventListener('DOMContentLoaded',()=>pAppStart());
